<?php
/**
 * Plugin Name: NESports Auto Updater V21
 * Description: High-precision 8x/10x supersampled vector SVGs and 4x Retina PNGs for Header and Footer logos.
 * Version: 21.0.0
 * Author: NESports
 */

function run_nesports_v21_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store'
    );

    if (is_dir(WP_PLUGIN_DIR)) {
        $scan = scandir(WP_PLUGIN_DIR);
        foreach ($scan as $f) {
            if ($f === '.' || $f === '..') continue;
            if (strpos($f, 'nesports-pro') === 0) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }
    
    $payloads = array(
        'templates/header-nesports.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'assets/images/logo-1.svg' => base64_decode(''),
        'assets/images/header-logo.svg' => base64_decode(''),
        'assets/images/logo-1.png' => base64_decode(''),
        'assets/images/footer-logo.svg' => base64_decode(''),
        'assets/images/footer-logo.png' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v21']) && $_GET['nesports_apply_v21'] === '1') {
        $res = run_nesports_v21_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_v21_update();
});
